	('5392e4c1-7072-481a-9da6-fe472b00ba48', 'fa33920b-7f58-49d9-88ce-cf71ec889733', NULL, 4, 'keyPointsCard', '{"main": {"icon": "team-fill", "title": "Définissez vos règles générales", "description": "Réglez en toute autonomie vos horaires et vos actes :<br/><i>durée, noms et consignes, ouverture aux nouveaux patients (ou non), etc.</i>"}, "navbar": {"variant": "appointment"}, "exception": {"icon": "user-fill", "items": [{"text": "pour un patient polypathologique, ouvrez-lui un acte de 30 min"}, {"text": "en cas d''abus, retirez l''accès à la consultation d''urgence "}, {"text": "pour un patient indésirable, bloquez-lui la prise de rdv"}], "title": "Faites des exceptions pour certains patients"}}', '2026-04-07 19:25:05.902181+00', '2026-04-10 13:18:38.611257+00', NULL),
