	('3a1c961c-b405-4c37-a2c8-49223131b523', 'fa33920b-7f58-49d9-88ce-cf71ec889733', NULL, 1, 'heroTitle', '{"title": "Filtrez toutes les demandes venant d''internet et du téléphone", "number": 1, "illustration": "/illustrations/toolbox1-header.webp"}', '2026-04-07 19:25:05.902181+00', '2026-04-12 07:56:19.046103+00', NULL),
	('15f2e3d4-572c-4218-8861-411727733992', 'fa33920b-7f58-49d9-88ce-cf71ec889733', NULL, 6, 'keyPointsCard', '{"main": {"icon": "team-fill", "items": [{"text": "par internet, sur votre site Internet dédié"}, {"text": "par téléphone de façon automatisée 24/7"}], "title": "Une prise de rendez-vous adaptée à tous vos patients :"}, "navbar": {"variant": "appointment"}, "exception": {"icon": "user-fill", "title": "Faites des exceptions pour certains patients", "description": "Transférez vos patients les plus à la marge vers votre (télé)secrétaire, sans appui touche."}}', '2026-04-07 19:25:05.902181+00', '2026-04-12 07:56:47.179994+00', NULL),
	('eff8cf6c-584c-4a1f-af06-bc761a367a3c', 'fa33920b-7f58-49d9-88ce-cf71ec889733', NULL, 9, 'card', '{"navbar": {"variant": "contact"}, "children": [{"type": "conditional", "payload": {"else": [{"type": "keyPointsCard", "payload": {"main": {"icon": "team-fill", "items": [{"text": "limite la charge mentale"}, {"text": "évite de commencer son lundi avec des messages à traiter"}, {"text": "rappel des consignes d''urgence (15 ou personnalisables)"}], "title": "En dehors de vos heures de présence, aucun message n''est pris."}, "exception": {"title": "Faites des exceptions pour certains patients", "description": "Restez joignable ponctuellement sans donner votre numéro de portable."}}}], "then": [{"type": "keyPointsCard", "payload": {"main": {"icon": "team-fill", "items": [{"text": "aucune interruption de service grâce à la prise de message"}, {"text": "possibilité d''orienter l''appel vers le médecin en cas d''urgence"}, {"text": "rappel des consignes d''urgence (15 ou personnalisables)"}], "title": "En cas d''absence ou d''indisponibilité de la secrétaire"}}}], "condition": {"op": "=", "value": "secretary", "variable": "personWhoHandleCalls"}}}, {"type": "conditional", "payload": {"else": [{"type": "keyPointsCard", "payload": {"main": {"icon": "team-fill", "items": [{"text": "prise de message avec retranscription dans votre interface"}, {"text": "prise de message ou transfert d''appel en cas d''urgence ressentie"}], "title": "Pendant vos heures de présence, au choix :"}}}], "then": [{"type": "keyPointsCard", "payload": {"main": {"icon": "team-fill", "items": [{"text": "diminution des transferts d''appels : Alice propose de prendre un message si le motif d''appel n''est pas urgent."}, {"text": "les appels restants sont transférés vers la secrétaire (urgence ressentie)"}, {"text": "diminution du nombre de messages laissés grâce aux consignes filtrantes (ex : aucun renouvellement traité par message)"}], "title": "Si votre secrétaire est disponible"}}}], "condition": {"op": "=", "value": "secretary", "variable": "personWhoHandleCalls"}}}]}', '2026-04-07 19:25:05.902181+00', '2026-04-07 21:56:31.429638+00', NULL),
	('5a371828-723d-431e-b041-5d9098ab5f2d', 'c09b9457-99ab-47b9-a53c-24e34b3d6383', NULL, 9, 'componentRef', '{"name": "HomeTool3_Summary", "props": {}}', '2026-04-08 18:52:03.38367+00', '2026-04-08 19:16:47.443698+00', NULL),
	('165e2e22-551b-4632-ab2f-e78fa8ea9a0c', 'c09b9457-99ab-47b9-a53c-24e34b3d6383', NULL, 5, 'toolContentSection', '{"name": "Imprévus", "title": "La gestion des imprévus", "video": {"src": "https://player.vimeo.com/video/1008363164?h=add4c825d0", "kind": "fixed"}, "anchorId": "section-unforeseen", "subtitle": "Restez flexible !", "advantageText": "En cas d’absence ou d’annulation de vos consultations, retards, objets trouvés... informez facilement vos patients concernés, grâce à l’envoi de SMS ou d’e-mails groupés.", "advantageTitle": "Les avantages"}', '2026-04-08 18:52:03.38367+00', '2026-04-08 19:16:47.20091+00', NULL),
	('0ad286bc-1adc-4dd7-be3f-290cf095d47f', 'c09b9457-99ab-47b9-a53c-24e34b3d6383', NULL, 6, 'toolContentSection', '{"name": "Campagnes", "title": "Les campagnes", "video": {"src": "https://player.vimeo.com/video/1008363110?h=e14d1a7977", "kind": "fixed"}, "anchorId": "section-campaign", "subtitle": "Communiquez de façon plus large", "advantageText": "Campagne de prévention, déménagement, arrivée ou départ d’un associé, cabinet en grève, ... Contactez en quelques clics toute ou partie de vos patients par SMS ou mail.", "advantageTitle": "Les avantages"}', '2026-04-08 18:52:03.38367+00', '2026-04-08 19:16:47.254934+00', NULL),
	('3be9d202-043a-4a56-8d3d-44692f3a1e84', 'c09b9457-99ab-47b9-a53c-24e34b3d6383', NULL, 7, 'toolContentSection', '{"name": "Annonces", "title": "Les annonces", "video": {"src": "https://player.vimeo.com/video/1008363043?h=7114b3c277", "kind": "fixed"}, "anchorId": "section-announcement", "subtitle": "Évitez de vous répéter !", "advantageText": "Paramétrez un message qui sera systématiquement lu par votre standardiste virtuelle et affiché sur votre site web pendant la durée de votre choix.", "advantageTitle": "Les avantages"}', '2026-04-08 18:52:03.38367+00', '2026-04-08 19:16:47.316872+00', NULL),
	('0ee17597-252c-4978-8e19-defa39783253', 'c09b9457-99ab-47b9-a53c-24e34b3d6383', NULL, 8, 'toolContentSection', '{"name": "Site Internet", "title": "Votre site internet indépendant", "video": {"src": "vimeo/911373095?hash=381aa9aa75", "kind": "fixed"}, "anchorId": "section-website", "subtitle": "Votre place n’est pas sur une plateforme", "advantageTitle": "Les avantages", "advantagePoints": ["facilitez la prise de rendez-vous de vos patients les plus connectés", "vous n’êtes pas sur une plateforme, vous êtes indépendant", "vous êtes propriétaire du nom de domaine (www.docteur-démo.fr)", "ajoutez des contenus, sans modération de notre part"]}', '2026-04-08 18:52:03.38367+00', '2026-04-08 19:16:47.376727+00', NULL),
	('39a6dfff-ac1f-4aad-a53a-45132c989678', 'c98e35fd-b170-40b6-b833-ccd5c5c9e1f9', NULL, 3, 'keyPointsCard', '{"main": {"icon": "home-fill", "title": "Bon à savoir", "description": "La durée de cette démo est estimée à <span class=\"font-medium\">30 minutes</span> mais vous avez la possibilité de quitter et reprendre à tout moment votre découverte en repassant par le lien que vous avez reçu par email."}, "inline": true, "hideHeader": true, "contentClass": "m-auto w-full max-w-[600px] px-1 md:px-0"}', '2026-04-08 19:38:14.592482+00', '2026-04-08 19:47:18.214454+00', NULL),
	('27a5b5dc-62e4-49ee-bbff-5a6cf87fe912', 'fa33920b-7f58-49d9-88ce-cf71ec889733', NULL, 7, 'faqCard', '{"navbar": {"variant": "appointment"}, "questions": [{"title": "Comment Alice identifie le patient ?", "blocks": [{"kind": "list", "items": [{"text": "si le patient a déjà une fiche avec un numéro de portable ou de fixe renseigné, il sera reconnu automatiquement grâce à son numéro"}]}, {"html": "si plusieurs patients ont le même numéro de téléphone associé (ex : la fiche d''un enfant a le même numéro que la fiche du parent), Alice demandera de préciser pour qui l''appelant souhaite prendre rendez-vous.", "kind": "callout"}, {"kind": "list", "items": [{"text": "si le patient n''a aucune fiche, elle sera créée automatiquement lors de sa première demande de rendez-vous"}]}, {"html": "un import de votre base patient est possible (gratuit)", "kind": "callout"}]}, {"title": "Et pour les patients qui appellent depuis un téléphone fixe ?", "blocks": [{"html": "Ils pourront aussi prendre RDV avec Alice :", "kind": "text"}, {"kind": "list", "items": [{"text": "si un email ou un portable est aussi attaché à leur fiche, ils recevront la confirmation du rendez-vous par sms ou e-mail"}, {"text": "s''ils n''ont qu''un téléphone fixe renseigné, aucune notification ne pourra être envoyée."}]}]}, {"title": "Comment Alice propose les prochains créneaux disponibles ?", "blocks": [{"kind": "list", "items": [{"text": "pour les patients âgés, elle privilégie les créneaux en pleine journée"}, {"text": "pour un patient en âge d''être actif, elle proposera plutôt ceux en début ou en fin de journée"}]}]}, {"title": "Et si les 3 propositions de rendez-vous ne conviennent pas ?", "blocks": [{"html": "Si le premier créneau proposé ne convient pas, le patient pourra demander les créneaux disponibles pour la date de son choix.", "kind": "text"}, {"url": "/mp3/hometool-1-2-example-rdv.mp3", "kind": "audio"}]}, {"title": "Comment gérer le SNP ?", "blocks": [{"html": "Lorsqu''il n''y a plus de place et selon votre présence, Alice pourra :", "kind": "text"}, {"else": [], "kind": "conditional", "then": [{"kind": "list", "items": [{"text": "orienter le patient vers un autre médecin du cabinet"}]}], "condition": {"op": "=", "value": true, "variable": "isInGroup"}}, {"kind": "list", "items": [{"text": "rappeler les consignes d''urgence et/ou de régulation"}, {"text": "vous transférer l''appel"}, {"text": "prendre un message, retranscrit dans votre interface"}]}]}]}', '2026-04-07 19:25:05.902181+00', '2026-04-10 08:17:57.52093+00', NULL),
	('7adba404-e176-44c7-b61f-86a43ebb359a', 'bc38aa1d-127f-4e1e-b95a-609c0def9a35', NULL, 1, 'componentRef', '{"name": "PresentationBrandHeader", "props": {"subTitle": "Découvrez MadeForMed"}}', '2026-04-08 07:37:17.720596+00', '2026-04-09 13:36:25.103193+00', NULL),
