	('5fd2b664-dfbd-489f-9ce7-71249cbe58b8', 'bc38aa1d-127f-4e1e-b95a-609c0def9a35', NULL, 2, 'componentRef', '{"name": "IntroFormFields", "props": {"cardIcon": "check-line", "nextStep": "STEP_OBSERVATION", "cardTitle": "Pour une démo personnalisée", "loadingText": "Veuillez patienter, nous accédons aux derniers échanges avec vous…", "nextButtonText": "Suivant", "cardDescription": "Merci de répondre à ces quelques questions :"}}', '2026-04-08 07:37:17.720596+00', '2026-04-08 07:37:17.720596+00', NULL),
