	('47e115a0-59e3-44b3-bf45-7cc964ed0224', 'cd3c2f3f-8d9d-4197-a5d5-c7455ccfd327', NULL, 3, 'faqCard', '{"questions": [{"title": "Quand mes patients reçoivent-ils des notifications ?", "blocks": [{"kind": "list", "items": [{"text": "confirmation / rappel de rdv : date, heure, nom du praticien, consignes"}, {"text": "partage d’un document"}, {"text": "lien pour accéder à une téléconsultation"}, {"text": "demande de paiement"}]}]}, {"title": "Comment sont notifiés mes patients pour les rendez-vous ?", "blocks": [{"kind": "list", "items": [{"text": "par un SMS (5x plus lu par vos patients), plutôt qu’un e-mail"}, {"text": "notification au nom du cabinet médical (marque “MadeForMed” invisible côté patient)"}, {"text": "consignes personnalisables, acte par acte"}]}]}, {"title": "Comment garder la maîtrise de mon organisation ?", "blocks": [{"kind": "list", "items": [{"text": "réservation possible de créneaux non visibles par les patients"}, {"text": "possibilité de fixer un rendez-vous à tout moment"}]}]}, {"title": "Comment gérer mes quelques VAD ?", "blocks": [{"kind": "list", "items": [{"text": "autorisation au cas par cas des demandes"}, {"text": "conversion en 2 clics des demandes en rendez-vous"}]}]}]}', '2026-04-08 15:49:31.140451+00', '2026-04-08 15:50:57.108763+00', NULL),
	('445aebb6-bf14-4b87-8a69-8791abb440da', 'c8d414d0-562d-4a1e-8945-7a983d181ba9', NULL, 3, 'keyPointsCard', '{"main": {"title": "", "extraDescriptions": ["40% des appels sont des “demandes de contact”.", "60% des appels concernent les rendez-vous.", "Tout le monde n’est pas capable de prendre rendez-vous en ligne."]}, "groups": [{"items": [{"text": "consignes non respectées"}, {"text": "patients mécontents du temps d’attente, notamment les lundis matin"}, {"else": {"text": "beaucoup de messages pour rien"}, "then": {"text": "1€ par appel juste pour dire non"}, "conditional": {"op": "=", "value": false, "variable": "acceptNewPatient"}}, {"else": {"text": "l’impression de payer cher par rapport à la qualité de service fournie"}, "then": {"text": "des secrétaires usées et une ligne saturée par des demandes de nouveaux patients"}, "conditional": {"op": "=", "value": false, "variable": "acceptNewPatient"}}], "title": "Les solutions existantes créent de nouveaux problèmes :", "variant": "secondary50"}, {"items": [{"text": "par internet ou téléphone"}, {"text": "pour un rendez-vous ou pour échanger avec le cabinet"}], "title": "Les solutions MadeForMed traitent toutes les demandes", "variant": "primary50"}]}', '2026-04-08 15:37:00.92075+00', '2026-04-08 15:39:27.36598+00', NULL),
